# IPTVPremium: Home: desenhos originais dos icones com interior perola ou grafite. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_red_gray.png'; Binary = $true; Allowed = @('02AC21B49DC91C479781ACAFF4210DF00018A16C7027698C29E145876CE27406'); MayCreate = $false; After = '80B3FB27411F1AC9D10293D05FE8DC2FA99AC903C41861897CF2773BBC41C964'; PayloadHash = '80B3FB27411F1AC9D10293D05FE8DC2FA99AC903C41861897CF2773BBC41C964'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_red_white.png'; Binary = $true; Allowed = @('326F84DEC7A90EE715E28BD027E07AB320ED0AB0B581973734B27C3673D0A6A0'); MayCreate = $false; After = 'C8B68BB3721D30D92E6289449BE91F5D710F2B6203C69C855DD8CCDEFE744A55'; PayloadHash = 'C8B68BB3721D30D92E6289449BE91F5D710F2B6203C69C855DD8CCDEFE744A55'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_purple_gray.png'; Binary = $true; Allowed = @('9B57677F1EC5697832DC6DD1B986F7FA2C81D280B7A6E393E846ACD130B47DD5'); MayCreate = $false; After = '86F272A353A1B5AB1DB474F264FD9389851E1367ED13FD86C28352786119D98B'; PayloadHash = '86F272A353A1B5AB1DB474F264FD9389851E1367ED13FD86C28352786119D98B'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_purple_white.png'; Binary = $true; Allowed = @('4D8C00438C79F04BCDF070F0EEC2D8FA27836745B90E8552CE40774B4CCA3D5B'); MayCreate = $false; After = '3F38D74A36B59FF145BC3502F9A1066DDF2E9ACBC72EB2F507E2CDA2D71A3D93'; PayloadHash = '3F38D74A36B59FF145BC3502F9A1066DDF2E9ACBC72EB2F507E2CDA2D71A3D93'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_pink_gray.png'; Binary = $true; Allowed = @('7E872D47C2BC06E1D900A8E4F5045226311EC7B5A08BCD4E8F7BA004503EB1C8'); MayCreate = $false; After = 'D7C9F64CE8FF5F57FB2C296165A7683E98BE16FEF97F14ED52CCBF287A31D674'; PayloadHash = 'D7C9F64CE8FF5F57FB2C296165A7683E98BE16FEF97F14ED52CCBF287A31D674'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_pink_white.png'; Binary = $true; Allowed = @('A27C681813E1764708C15F5831ACEA264A8A4F67DE6EA347C69421A3D611A0C6'); MayCreate = $false; After = 'E82F1946D988B98E2F96507B51B32D7F9427803D66F828B92C8F09BDAECB701F'; PayloadHash = 'E82F1946D988B98E2F96507B51B32D7F9427803D66F828B92C8F09BDAECB701F'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_blue_gray.png'; Binary = $true; Allowed = @('E3EF4F8E8E6005EB3623F3EF0316E16F136708A2D99D87F499B3BDEDEB38EB0C'); MayCreate = $false; After = '74742A8948EB23171A4AC9A1C557A3D70DDEC9D20BD0A648130FB8FF39B151AB'; PayloadHash = '74742A8948EB23171A4AC9A1C557A3D70DDEC9D20BD0A648130FB8FF39B151AB'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_blue_white.png'; Binary = $true; Allowed = @('47CA95D3DDF61665CDE08D20DB6960F9E99534A667F3E42615E28355ABC2A373'); MayCreate = $false; After = '5ED5298F59A06CD377E7474EFFC0CCC31DFC5F37ADEFD0DE734C2CA54DA5A5AB'; PayloadHash = '5ED5298F59A06CD377E7474EFFC0CCC31DFC5F37ADEFD0DE734C2CA54DA5A5AB'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_gold_gray.png'; Binary = $true; Allowed = @('5E703A5F8A4BE6D0F97D4273FD18066C288557336F7E8D7E4270B040B78904A8'); MayCreate = $false; After = '13619A2BDE48A2C3345B1CEA0C645A604B4CD8321E8696FF72088EE2E332836A'; PayloadHash = '13619A2BDE48A2C3345B1CEA0C645A604B4CD8321E8696FF72088EE2E332836A'; Data = '' },
    @{ Path = 'app/src/main/res/drawable-nodpi/home_original_gold_white.png'; Binary = $true; Allowed = @('6924F70B7D686D6FDB26324BB016EB08F4662B085E7EF11558E21FD80E7274AC'); MayCreate = $false; After = '874F508E60E70A69C87AD2D12714954B78665A318EFD4A05CEE17BB905420A90'; PayloadHash = '874F508E60E70A69C87AD2D12714954B78665A318EFD4A05CEE17BB905420A90'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/home/MarbleHomePngAssets.kt'; Binary = $false; Allowed = @('B1DD636944CAD26E05638BD49FDD0A89E3B280F94F17939AF78F68F014667056'); MayCreate = $false; After = '0621C12EC264F215087E9AA41EC95358A35CDFA3EA1969F56D00DD0ADD3095C1'; PayloadHash = '0621C12EC264F215087E9AA41EC95358A35CDFA3EA1969F56D00DD0ADD3095C1'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = if ($file.Binary) { Get-BytesHash $original } else { Get-TextHash $original }
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/icones-originais-cores-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: icones originais com cores internas perola e grafite.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
